def split(total_cents, people):
    """Share total_cents among people as evenly as whole cents allow; the first few pay a cent more."""
    if people < 1:
        raise ValueError('split() needs at least one person')
    share, remainder = divmod(total_cents, people)
    return [share + (1 if index < remainder else 0) for index in range(people)]

